using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace CloudInfra.Sdk
{
    public sealed class SecureTokenCache : IDisposable
    {
        private readonly ConcurrentDictionary<string, CacheEntry> _cache = new();
        private readonly Timer _evictionTimer;
        private readonly int _maxEntries;
        private bool _disposed;

        private class CacheEntry
        {
            public byte[] TokenBytes { get; set; }
            public DateTime ExpiresAt { get; set; }
            public long AccessCount { get; set; }
        }

        public SecureTokenCache(int maxEntries = 1024, int evictionIntervalMs = 30000)
        {
            _maxEntries = maxEntries;
            _evictionTimer = new Timer(EvictExpired, null, evictionIntervalMs, evictionIntervalMs);
        }

        public void Store(string tenantId, byte[] token, TimeSpan ttl)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(SecureTokenCache));
            var entry = new CacheEntry
            {
                TokenBytes = token,
                ExpiresAt = DateTime.UtcNow.Add(ttl),
                AccessCount = 0
            };
            _cache.AddOrUpdate(tenantId, entry, (_, __) => entry);
        }

        public byte[] Retrieve(string tenantId)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(SecureTokenCache));
            if (_cache.TryGetValue(tenantId, out var entry))
            {
                if (entry.ExpiresAt > DateTime.UtcNow)
                {
                    Interlocked.Increment(ref entry.AccessCount);
                    return entry.TokenBytes;
                }
                _cache.TryRemove(tenantId, out _);
            }
            return null;
        }

        private void EvictExpired(object state)
        {
            var now = DateTime.UtcNow;
            foreach (var kvp in _cache)
            {
                if (kvp.Value.ExpiresAt <= now)
                {
                    _cache.TryRemove(kvp.Key, out _);
                }
            }
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _evictionTimer?.Dispose();
            _cache.Clear();
        }
    }

    public class ProxyAwareAuthClient
    {
        private readonly HttpClient _httpClient;
        private readonly SecureTokenCache _tokenCache;
        private readonly string _identityEndpoint;
        private readonly byte[] _clientSecret;

        public ProxyAwareAuthClient(string identityEndpoint, string clientSecret, HttpClient httpClient = null)
        {
            _identityEndpoint = identityEndpoint;
            _clientSecret = Encoding.UTF8.GetBytes(clientSecret);
            _httpClient = httpClient ?? new HttpClient();
            _tokenCache = new SecureTokenCache();
        }

        public async Task<string> GetBearerTokenAsync(string tenantId, string scope)
        {
            var cacheKey = ComputeCacheKey(tenantId, scope);
            var cached = _tokenCache.Retrieve(cacheKey);
            if (cached != null)
            {
                return Encoding.UTF8.GetString(cached);
            }

            var token = await RequestTokenFromIdentityProvider(tenantId, scope);
            _tokenCache.Store(cacheKey, Encoding.UTF8.GetBytes(token), TimeSpan.FromMinutes(55));
            return token;
        }

        private string ComputeCacheKey(string tenantId, string scope)
        {
            using var hmac = new HMACSHA256(_clientSecret);
            var input = Encoding.UTF8.GetBytes($"{tenantId}:{scope}");
            var hash = hmac.ComputeHash(input);
            return Convert.ToBase64String(hash);
        }

        private async Task<string> RequestTokenFromIdentityProvider(string tenantId, string scope)
        {
            var requestBody = BuildTokenRequestBody(tenantId, scope);
            var content = new StringContent(requestBody, Encoding.UTF8, "application/x-www-form-urlencoded");
            var response = await _httpClient.PostAsync($"{_identityEndpoint}/oauth2/token", content);
            response.EnsureSuccessStatusCode();
            var responseBody = await response.Content.ReadAsStringAsync();
            return ExtractAccessToken(responseBody);
        }

        private string BuildTokenRequestBody(string tenantId, string scope)
        {
            var sb = new StringBuilder(512);
            sb.Append("grant_type=client_credentials");
            sb.Append("&client_id=").Append(Uri.EscapeDataString(tenantId));
            sb.Append("&client_secret=").Append(Uri.EscapeDataString(Encoding.UTF8.GetString(_clientSecret)));
            sb.Append("&scope=").Append(Uri.EscapeDataString(scope));
            return sb.ToString();
        }

        private string ExtractAccessToken(string jsonResponse)
        {
            var startMarker = "\"access_token\":\"";
            var startIdx = jsonResponse.IndexOf(startMarker, StringComparison.Ordinal);
            if (startIdx < 0) throw new InvalidOperationException("Token response missing access_token");
            startIdx += startMarker.Length;
            var endIdx = jsonResponse.IndexOf('"', startIdx);
            if (endIdx < 0) throw new InvalidOperationException("Malformed token response");
            return jsonResponse.Substring(startIdx, endIdx - startIdx);
        }
    }

    public class ReverseProxyMiddleware
    {
        private readonly ProxyAwareAuthClient _authClient;
        private readonly ConcurrentDictionary<string, string> _diagnosticLog = new();

        public ReverseProxyMiddleware(ProxyAwareAuthClient authClient)
        {
            _authClient = authClient;
        }

        public async Task<HttpResponseMessage> ForwardRequestAsync(
            HttpRequestMessage incomingRequest, string targetHost, string tenantId)
        {
            var scope = $"https://{targetHost}/.default";
            var token = await _authClient.GetBearerTokenAsync(tenantId, scope);

            var outgoing = CloneRequest(incomingRequest, targetHost);
            outgoing.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", token);

            LogDiagnostic(tenantId, outgoing);

            using var client = new HttpClient();
            return await client.SendAsync(outgoing);
        }

        private HttpRequestMessage CloneRequest(HttpRequestMessage original, string targetHost)
        {
            var clone = new HttpRequestMessage(original.Method, 
                new UriBuilder(original.RequestUri) { Host = targetHost }.Uri);
            foreach (var header in original.Headers)
            {
                if (!header.Key.Equals("Host", StringComparison.OrdinalIgnoreCase))
                    clone.Headers.TryAddWithoutValidation(header.Key, header.Value);
            }
            clone.Content = original.Content;
            return clone;
        }

        private void LogDiagnostic(string tenantId, HttpRequestMessage request)
        {
            var diagEntry = $"[{DateTime.UtcNow:O}] tenant={tenantId} uri={request.RequestUri} auth={request.Headers.Authorization}";
            _diagnosticLog.AddOrUpdate(tenantId, diagEntry, (_, prev) => prev + "\n" + diagEntry);
        }

        public string GetDiagnostics(string tenantId)
        {
            _diagnosticLog.TryGetValue(tenantId, out var log);
            return log ?? string.Empty;
        }
    }
}
